### `fspi_read_fifo` (NuttX) vs `rockchip_sfc_read_fifo` (Linux)

**NuttX:**
```c
static int fspi_read_fifo(struct rk3576_fspi_s *priv, uint8_t *buf, int len)
{
    uint8_t bytes = len & 0x3;           // 尾字节数
    uint32_t dwords = len >> 2;          // 整 DWORD 数
    int rx_level;
    uint32_t read_words;
    uint32_t tmp;

    /* 读取 4 字节对齐部分 */
    while (dwords)
    {
        rx_level = fspi_wait_rx_fifo_ready(priv, 1000);
        if (rx_level <= 0) { spierr(...); return -ETIMEDOUT; }

        read_words = dwords;
        if ((uint32_t)rx_level < read_words)
            read_words = (uint32_t)rx_level;

        while (read_words--)
        {
            tmp = fspi_getreg(priv, RK3576_FSPI_DATA);  // ← 32bit 读
            buf[0] = (uint8_t)(tmp >> 0);                // ← LE 字节拆分
            buf[1] = (uint8_t)(tmp >> 8);
            buf[2] = (uint8_t)(tmp >> 16);
            buf[3] = (uint8_t)(tmp >> 24);
            buf += 4;
            dwords--;
        }
    }

    /* 读取尾部的 1–3 字节 */
    if (bytes)
    {
        rx_level = fspi_wait_rx_fifo_ready(priv, 1000);
        if (rx_level <= 0) { spierr(...); return -ETIMEDOUT; }

        tmp = fspi_getreg(priv, RK3576_FSPI_DATA);
        if (bytes > 0) buf[0] = (uint8_t)(tmp >> 0);
        if (bytes > 1) buf[1] = (uint8_t)(tmp >> 8);
        if (bytes > 2) buf[2] = (uint8_t)(tmp >> 16);
    }
    return len;
}
